param([ValidateSet('01','02','03')][string]$RunId='01')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$private=Join-Path $root 'server/.local/p27c';$port=3106+[int]$RunId;$record=Join-Path $private "uat-$RunId-server.json"
if(Test-Path -LiteralPath $record){$prior=Get-Content -LiteralPath $record -Raw|ConvertFrom-Json;if($prior.schema -ne "upms_test_p27c_uat_20261023_$RunId"){throw 'UAT record identity mismatch'};$existing=Get-Process -Id $prior.serverPid -ErrorAction SilentlyContinue;if($existing -or (Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue)){throw 'A process or listener still exists. Use health and the verified Stop-UPMSUAT helper; no automatic replacement.'};Move-Item -LiteralPath $record -Destination (Join-Path $private "uat-$RunId-server-stale-$([DateTime]::UtcNow.Ticks).json")};if(Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue){throw 'Reviewed demo port is busy'}
$launcher=Start-Process pwsh -ArgumentList @('-NoProfile','-File',(Join-Path $PSScriptRoot 'Invoke-UPMSUAT.ps1'),'-Action','Serve','-RunId',$RunId) -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput (Join-Path $private "uat-$RunId-server.stdout.log") -RedirectStandardError (Join-Path $private "uat-$RunId-server.stderr.log") -PassThru
$listener=$null;for($n=0;$n -lt 40;$n++){Start-Sleep -Milliseconds 500;$listener=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue;if($listener){break};if($launcher.HasExited){throw 'Demo launcher exited; preserve evidence'}};if(-not $listener){throw 'Demo readiness timeout'};$process=Get-CimInstance Win32_Process -Filter "ProcessId=$($listener.OwningProcess)";if($process.ParentProcessId -ne $launcher.Id -or $process.CommandLine -notmatch 'server[\/]tools[\/]uat-serve\.mjs'){throw 'Demo process identity mismatch'};$node=Get-Process -Id $listener.OwningProcess
@{serverPid=$node.Id;launcherPid=$launcher.Id;startTicks=$node.StartTime.ToUniversalTime().Ticks;schema="upms_test_p27c_uat_20261023_$RunId";url="http://127.0.0.1:$port/management"}|ConvertTo-Json|Set-Content -LiteralPath $record
& (Join-Path $PSScriptRoot 'Invoke-UPMSUAT.ps1') -Action Health -RunId $RunId
